def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # The colored forms are overlays; draw the 8-colored reference shape over every
    # matching silhouette among the other colored shapes.
    def get_components():
        seen=set(); result=[]
        for y in range(h):
            for x in range(w):
                c=grid[y][x]
                if not c or (y,x) in seen: continue
                todo=[(y,x)];seen.add((y,x));p=[]
                while todo:
                    a,b=todo.pop();p.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(a+da,b+db)
                        if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]]==c and q not in seen:
                            seen.add(q);todo.append(q)
                result.append((c,p))
        return result
    def norm(p):
        my=min(a for a,b in p); mx=min(b for a,b in p)
        return frozenset((a-my,b-mx) for a,b in p)
    comp=get_components(); keys=[norm(p) for c,p in comp if c==8]
    # Match all eight orientations, accounting for rotation/reflection.
    def forms(s):
        result=set()
        for flip in (1,-1):
            for k in range(4):
                pts=[]
                for y,x in s:
                    x*=flip
                    for _ in range(k): y,x=x,-y
                    pts.append((y,x))
                my=min(y for y,x in pts);mx=min(x for y,x in pts)
                result.add(frozenset((y-my,x-mx) for y,x in pts))
        return result
    kforms=set().union(*(forms(k) for k in keys)) if keys else set()
    for c,p in comp:
        if c!=8 and norm(p) in kforms:
            for y,x in p: out[y][x]=8
    return out
