    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    seen=set(); groups=[]
    for y in range(h):
      for x in range(w):
        c=grid[y][x]
        if not c or (y,x) in seen: continue
        todo=[(y,x)];seen.add((y,x));pts=[]
        while todo:
          a,b=todo.pop();pts.append((a,b))
          for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(a+da,b+db)
            if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]]==c and q not in seen:
              seen.add(q);todo.append(q)
        groups.append((c,pts))
    def shape(p):
      ya=min(y for y,x in p);xa=min(x for y,x in p)
      return frozenset((y-ya,x-xa) for y,x in p)
    def variants(s):
      vs=set()
      for f in (1,-1):
       for r in range(4):
        pp=[]
        for y,x in s:
          x*=f
          for _ in range(r): y,x=x,-y
          pp.append((y,x))
        my=min(y for y,x in pp);mx=min(x for y,x in pp)
        vs.add(frozenset((y-my,x-mx) for y,x in pp))
      return vs
    # Rule: same-shaped objects are exchanged/recolored cyclically to the color of
    # the matching reference/other shape; demonstrated: 1 matches 6, 7, and 9 forms.
    # Recolor each 1 object to color of the matching non-1 object, selecting key color by size/order.
    # Demonstrations establish the corresponding shapes: 3x3 hollow-corner form -> 6;
    # 2x2 L -> 9; singleton-adjacent pattern -> key as shown.
    refs={}
    for c,p in groups:
      if c!=1: refs.setdefault(variants(shape(p)),c)
    for c,p in groups:
      if c==1:
        v=variants(shape(p))
        for vv,target in refs.items():
          if v & vv:
            for y,x in p: out[y][x]=target
            break
    return out
