def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    comps = []
    for y in range(h):
        for x in range(w):
            c = grid[y][x]
            if c == 0 or (y, x) in seen:
                continue
            stack = [(y, x)]
            seen.add((y, x))
            pts = []
            while stack:
                a, b = stack.pop()
                pts.append((a, b))
                for da, db in ((1,0),(-1,0),(0,1),(0,-1)):
                    q = (a+da, b+db)
                    if 0 <= q[0] < h and 0 <= q[1] < w and grid[q[0]][q[1]] == c and q not in seen:
                        seen.add(q)
                        stack.append(q)
            comps.append((c, pts))

    def canonical(pts):
        # Canonical polyomino up to rotations and reflections.
        result = []
        for reflect in (1, -1):
            for rot in range(4):
                transformed = []
                for y, x in pts:
                    x *= reflect
                    for _ in range(rot):
                        y, x = x, -y
                    transformed.append((y, x))
                my = min(y for y, x in transformed)
                mx = min(x for y, x in transformed)
                result.append(tuple(sorted((y-my, x-mx) for y, x in transformed)))
        return min(result)

    templates = {}
    for color, pts in comps:
        if color != 1:
            templates.setdefault(canonical(pts), color)
    for color, pts in comps:
        if color == 1:
            target = templates.get(canonical(pts))
            if target is not None:
                for y, x in pts:
                    out[y][x] = target
    return out
